    return new RewardBatchSummary(
            batch.getId(),
            batch.getTaskId(),
            taskTitle,
            batch.getBatchNo(),
            batch.getStatus(),
            batch.getSettleScope(),
            batch.getCurrencyCode(),
            batch.getRewardRuleSnapshotJson(),
            batch.getTargetTotalCount(),
            batch.getEffectiveTotalCount(),
            batch.getUserTotalCount(),
            batch.getTotalAmount(),
            batch.getConfirmedBy(),
            batch.getConfirmedAt(),
            batch.getPaidAt(),
            batch.getReversedAt(),
            batch.getExportFileId(),
            batch.getRemark(),
            batch.getCreatedAt());
}
